                          "props": {"size": "medium"},
                          "children": [
                            {
                              "component": "SectionLabel",
                              "children": ["Quality"],
                            },
                            {
                              "component": "Inline",
                              "children": ["Nine of twelve checks passed."],
                            },
                          ],
                        },
                      ],
