                },
                {
                  "component": "Specimen",
                  "props": {"label": "medium"},
                  "children": [
                    {
                      "component": "IconButton",
                      "props": {"label": "Copy (medium)", "size": "medium"},
                      "children": [
                        {
                          "component": "Icon",
                          "props": {"name": "Copy20Regular", "size": 16},
                        },
