                      "props": {
                        "display": "inline-flex",
                        "gap": "spacing.1",
                        "align": "center",
                        "tone": "muted",
                      },
                      "children": [
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["Ctrl"],
                        },
                        "+",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["Shift"],
                        },
                        "+",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small", "variant": "key"},
                          "children": ["P"],
                        },
                      ],
                    },
                  ],
