                {
                  "component": "Specimen",
                  "props": {"label": "as a hint"},
                  "children": [
                    {
                      "component": "KeyCap",
                      "props": {"size": "small"},
                      "children": ["⌘⇧K"],
                    },
                  ],
                },
                {
                  "component": "Specimen",
                  "props": {"label": "in prose"},
                  "children": [
                    {
                      "component": "Inline",
                      "children": [
                        "Open the command palette with ",
                        {
                          "component": "KeyCap",
                          "props": {"size": "small"},
                          "children": ["⌘K"],
                        },
                        ", then type a document name.",
                      ],
                    },
                  ],
                },
