              "component": "Box",
              "props": {
                "role": "radiogroup",
                "display": "flex",
                "gap": "spacing.2",
                "wrap": true,
              },
              "children": [
                {
                  "component": "OptionCard",
                  "props": {
                    "title": "primary",
                    "selected": true,
                    "tint": "primary",
                  },
                },
                {
                  "component": "OptionCard",
                  "props": {
                    "title": "neutral",
                    "selected": true,
                    "tint": "neutral",
