  "components/otpfield/in a form": {
    "content": {
      "component": "Col",
      "props": {"width": 320, "gap": "spacing.4"},
      "children": [
        {
          "component": "Callout",
          "props": {"tint": "info"},
          "children": ["We sent a six-digit code to ada@example.com."],
        },
        {
          "component": "FormField",
          "props": {"label": "Verification code"},
          "derive": {
            "hint": {
              "if": {
                "and": [
                  {
                    "eq": [
                      {
                        "length": {"state": "code"},
                      },
                      6,
                    ],
                  },
                  {
                    "not": {
                      "eq": [
                        {"state": "code"},
                        "204815",
                      ],
                    },
                  },
                ],
              },
              "then": "That code did not match",
              "else": "It expires in 10 minutes",
            },
            "state": {
              "if": {
                "and": [
                  {
                    "eq": [
                      {
                        "length": {"state": "code"},
                      },
                      6,
                    ],
                  },
                  {
                    "not": {
                      "eq": [
                        {"state": "code"},
                        "204815",
                      ],
                    },
                  },
                ],
              },
              "then": "error",
              "else": "default",
            },
          },
          "children": [
            {
              "component": "OtpField",
              "props": {"length": 6, "groupAfter": 3},
              "derive": {
                "state": {
                  "if": {
                    "and": [
                      {
                        "eq": [
                          {
                            "length": {"state": "code"},
                          },
                          6,
                        ],
                      },
                      {
                        "not": {
                          "eq": [
                            {"state": "code"},
                            "204815",
                          ],
                        },
                      },
                    ],
                  },
                  "then": "error",
                  "else": "default",
                },
              },
              "bind": {"value": "code"},
            },
          ],
        },
        {
          "component": "Button",
          "props": {"variant": "filled"},
          "derive": {
            "disabled": {
              "not": {
                "gte": [
                  {
                    "length": {"state": "code"},
                  },
                  6,
                ],
              },
            },
          },
          "children": ["Verify"],
        },
      ],
    },
    "state": {"code": ""},
