  "components/steplist/advancing": {
    "state": {"stage": 0},
    "timers": [
      {
        "every": 1400,
        "set": "stage",
        "value": {
          "if": {
            "gte": [
              {"state": "stage"},
              5,
            ],
          },
          "then": 0,
          "else": {
            "add": [
              {"state": "stage"},
              1,
            ],
          },
        },
      },
    ],
    "content": {
      "component": "Box",
      "props": {"width": 416},
      "children": [
        {
          "component": "Card",
          "children": [
            {
              "component": "SectionLabel",
              "children": ["handbook.docx"],
            },
            {
              "component": "Progress",
              "id": "progress",
              "derive": {
                "value": {
                  "multiply": [
                    {"state": "stage"},
                    20,
                  ],
                },
              },
            },
            {
              "component": "StepList",
              "children": [
                {
                  "component": "Step",
                  "id": "stage-0",
                  "props": {"label": "Parsed the document"},
                  "derive": {
                    "status": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          1,
                        ],
                      },
                      "then": "done",
                      "else": {
                        "if": {
                          "eq": [
                            {"state": "stage"},
                            0,
                          ],
                        },
                        "then": "active",
                        "else": "idle",
                      },
                    },
                    "meta": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          1,
                        ],
                      },
                      "then": "15 pages",
                      "else": "",
                    },
                  },
                },
                {
                  "component": "Step",
                  "id": "stage-1",
                  "props": {"label": "Extracted segments"},
                  "derive": {
                    "status": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          2,
                        ],
                      },
                      "then": "done",
                      "else": {
                        "if": {
                          "eq": [
                            {"state": "stage"},
                            1,
                          ],
                        },
                        "then": "active",
                        "else": "idle",
                      },
                    },
                    "meta": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          2,
                        ],
                      },
                      "then": "392",
                      "else": "",
                    },
                  },
                },
                {
                  "component": "Step",
                  "id": "stage-2",
                  "props": {"label": "Translating"},
                  "derive": {
                    "status": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          3,
                        ],
                      },
                      "then": "done",
                      "else": {
                        "if": {
                          "eq": [
                            {"state": "stage"},
                            2,
                          ],
                        },
                        "then": "active",
                        "else": "idle",
                      },
                    },
                    "meta": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          3,
                        ],
                      },
                      "then": "168 / 392",
                      "else": "",
                    },
                  },
                },
                {
                  "component": "Step",
                  "id": "stage-3",
                  "props": {"label": "Applying the glossary"},
                  "derive": {
                    "status": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          4,
                        ],
                      },
                      "then": "done",
                      "else": {
                        "if": {
                          "eq": [
                            {"state": "stage"},
                            3,
                          ],
                        },
                        "then": "active",
                        "else": "idle",
                      },
                    },
                  },
                },
                {
                  "component": "Step",
                  "id": "stage-4",
                  "props": {"label": "Rebuilding the layout"},
                  "derive": {
                    "status": {
                      "if": {
                        "gte": [
                          {"state": "stage"},
                          5,
                        ],
                      },
                      "then": "done",
                      "else": {
                        "if": {
                          "eq": [
                            {"state": "stage"},
                            4,
                          ],
                        },
                        "then": "active",
                        "else": "idle",
                      },
                    },
                  },
                },
              ],
            },
          ],
        },
      ],
    },
    "checkpoints": [
      {
        "id": "initial",
        "steps": [],
        "expect": {"stage": 0},
        "expectText": {"stage-0": "Parsed the document"},
      },
      {
        "id": "next",
        "steps": [
          {"action": "advance", "milliseconds": 1400},
        ],
        "expect": {"stage": 1},
        "expectText": {
          "stage-0": "Parsed the document15 pages",
          "stage-1": "Extracted segments",
        },
      },
      {
        "id": "finished",
        "steps": [
          {"action": "advance", "milliseconds": 7000},
        ],
        "expect": {"stage": 5},
        "expectText": {"stage-2": "Translating168 / 392"},
      },
      {
        "id": "wrapped",
        "steps": [
          {"action": "advance", "milliseconds": 8400},
        ],
        "expect": {"stage": 0},
        "expectText": {"stage-0": "Parsed the document"},
      },
    ],
    "id": "components-steplist--advancing",
    "title": "Components/StepList",
    "name": "Advancing",
    "layout": "centered",
  },
