List<StoryGroup> generatedGroups(List<StoryGroup> groups) {
  final result = [
    for (final group in groups)
      StoryGroup(group.name, [
        for (final page in group.pages) StoryPage(page.name, [...page.stories]),
      ]),
  ];
  for (final scene in generatedScenes.values) {
    final parts = (scene['title'] as String).split('/');
    final groupName = parts.first;
    final pageName = parts.skip(1).join('/');
    var groupIndex = result.indexWhere((group) => group.name == groupName);
    if (groupIndex < 0) {
      groupIndex = result.length;
      result.add(StoryGroup(groupName, []));
    }
    final pages = result[groupIndex].pages;
    var pageIndex = pages.indexWhere((page) => page.name == pageName);
    if (pageIndex < 0) {
      pageIndex = pages.length;
      pages.add(StoryPage(pageName, []));
    }
    final stories = pages[pageIndex].stories;
    final index = stories.indexWhere(
      (story) =>
          (story.sourceId ?? storyId(groupName, pageName, story.name)) ==
              scene['id'] ||
          story.name.toLowerCase() == (scene['name'] as String).toLowerCase(),
    );
    final generated = Story(
      scene['name'],
      (context) => GeneratedScene(key: ValueKey(scene['id']), scene: scene),
      sourceId: scene['id'],
      layout: switch (scene['layout']) {
        'fullscreen' => StoryLayout.fullscreen,
        'page' => StoryLayout.page,
        _ => StoryLayout.centered,
      },
    );
    if (index < 0) {
      stories.add(generated);
    } else {
      stories[index] = generated;
    }
  }
