  int rank(List<String> order, String key) {
    final i = order.indexOf(key);
    return i < 0 ? order.length : i;
  }

  for (final group in result) {
    group.pages.sort(
      (a, b) => rank(
        pageOrder,
        '${group.name}/${a.name}',
      ).compareTo(rank(pageOrder, '${group.name}/${b.name}')),
    );
    for (final page in group.pages) {
      page.stories.sort(
        (a, b) =>
            rank(
              storyOrder,
              a.sourceId ?? storyId(group.name, page.name, a.name),
            ).compareTo(
              rank(
                storyOrder,
                b.sourceId ?? storyId(group.name, page.name, b.name),
              ),
            ),
      );
    }
  }
  return result;
}
